1	package clinical
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"sort"
9		"strings"
10		"time"
11	)
12	
13	// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
14	// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
15	type PackageDelivery struct {
16		ExchangeID ID
17		Status     string
18		Digest     string
19		CreatedAt  time.Time
20		Package    Package
21	}
22	
23	// ReceiptConfirmation 是接收方登记回执后得到的确认。
24	// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
25	// 授权失效或患者停用后登记回执也只返回该确认。
26	type ReceiptConfirmation struct {
27		ExchangeID   ID
28		Status       string
29		Outcome      string
30		RegisteredAt time.Time
31	}
32	
33	// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
34	// 指定接收方。
35	//
36	// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
37	// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
38	// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
39	// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
40	// 不存在或跨患者的引用、夹带草稿、记录不被绑定授权覆盖、授权不符一律拒绝，
41	// 不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
42	//
43	// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
44	// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
45	// 更正或有新版本、新增记录都不会改写已创建的包。
46	//
47	// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
48	// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
49	// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
50	// 命中已保存交换的重试只是读取既有结果、不产生任何状态变更，因此不再落盘：
51	// 即使本地保存条件当前不可用，重试也成功返回正式保存的那份交换。
52	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
53		if !actor.valid() || !actor.IsInternal() {
54			return Exchange{}, ErrAccessDenied
55		}
56		if patientID == "" {
57			return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
58		}
59		if strings.TrimSpace(receiverID) == "" {
60			return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
61		}
62		if strings.TrimSpace(authorizationID) == "" {
63			return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
64		}
65		if strings.TrimSpace(requestID) == "" {
66			return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
67		}
68		if len(recordIDs) == 0 {
69			return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
70		}
71		for _, rid := range recordIDs {
72			if strings.TrimSpace(rid) == "" {
73				return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
74			}
75		}
76		wanted := uniqueSortedIDs(recordIDs)
77	
78		var result Exchange
79		err := s.mutate(func(snap *snapshot) error {
80			// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
81			// 都只返回原结果（重试不是新建）。
82			if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
83				if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
84					return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
85				}
86				result = *existing
87				if existing.Receipt != nil {
88					r := *existing.Receipt
89					result.Receipt = &r
90				}
91				result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
92				// 命中已保存的交换：没有任何状态变更，不落盘——即使本地保存
93				// 条件当前不可用，重试也必须成功返回原交换。
94				return errUnchanged
95			}
96	
97			// 首次创建：患者必须存在且未停用。
98			if _, err := requireActivePatient(snap, patientID); err != nil {
99				return err
100			}
101	
102			// 绑定授权必须存在、属于该患者与接收方、当前有效。
103			a := snap.Authorizations[authorizationID]
104			if a == nil {
105				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
106			}
107			if a.PatientID != patientID {
108				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
109					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
110			}
111			if a.ReceiverID != receiverID {
112				return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
113					ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
114			}
115			now := s.now()
116			if !a.ActiveAt(now) {
117				// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
118				return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
119			}
120	
121			// 覆盖只由绑定的这一条授权解释：整类范围或限定范围，与接收方查阅
122			// 共用同一套判定（grantCoverage）。同一接收方的其他授权不并入其中，
123			// 因此不能借用其他授权补足覆盖。
124			coverage := newGrantCoverage()
125			coverage.add(a)
126	
127			// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
128			pkg := Package{PatientID: patientID, ReceiverID: receiverID}
129			for _, rid := range wanted {
130				r := snap.Records[rid]
131				if r == nil {
132					return fmt.Errorf("%w: record %q", ErrNotFound, rid)
133				}
134				if r.PatientID != patientID {
135					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
136						ErrMismatchedPatient, rid, r.PatientID, patientID)
137				}
138				if r.CurrentVersionID == "" {
139					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
140						ErrInvalidArgument, rid)
141				}
142				v := snap.Versions[r.CurrentVersionID]
143				if v == nil {
144					return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
145				}
146				// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
147				// 夹带一条未覆盖记录即整包拒绝，不保存其中合法部分。
148				if !coverage.coversRecord(r) {
149					return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
150						ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
151				}
152				pkg.Records = append(pkg.Records, PackagedRecord{
153					EncounterID: r.EncounterID,
154					Category:    r.Category,
155					RecordID:    r.ID,
156					VersionID:   v.ID,
157					Version:     v.Number,
158					EffectiveAt: v.CreatedAt,
159					Content:     v.Content,
160				})
161			}
162	
163			x := &Exchange{
164				ID:              newID("exch"),
165				PatientID:       patientID,
166				ReceiverID:      receiverID,
167				AuthorizationID: authorizationID,
168				RequestID:       requestID,
169				CreatorID:       actor.ID,
170				Status:          ExchangePending,
171				Digest:          packageDigest(pkg),
172				Package:         pkg,
173				CreatedAt:       now,
174			}
175			snap.Exchanges[x.ID] = x
176			s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
177			result = *x
178			result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
179			return nil
180		})
181		return result, err
182	}
183	
184	// FetchPackage 供指定接收方凭交换标识取包。
185	//
186	// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
187	// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
188	// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
189	// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
190	// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
191	// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
192	// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
193	// 摘要、记录标识或交换状态。
194	// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
195	//
196	// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
197	// 重新打包，包内版本与内容仍以创建时保存的为准。
198	func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
199		if !actor.valid() || actor.Kind != "receiver" {
200			return PackageDelivery{}, ErrAccessDenied
201		}
202		if strings.TrimSpace(exchangeID) == "" {
203			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
204		}
205	
206		var out PackageDelivery
207		err := s.view(func(snap *snapshot) error {
208			// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
209			// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
210			// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
211			now := s.now()
212			x := snap.Exchanges[exchangeID]
213			if x == nil || x.ReceiverID != actor.ID {
214				// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
215				return ErrAccessDenied
216			}
217			p := snap.Patients[x.PatientID]
218			if p == nil || p.Deactivated {
219				return ErrAccessDenied
220			}
221			// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
222			a := snap.Authorizations[x.AuthorizationID]
223			if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
224				return ErrAccessDenied
225			}
226			out = PackageDelivery{
227				ExchangeID: x.ID,
228				Status:     x.Status,
229				Digest:     x.Digest,
230				CreatedAt:  x.CreatedAt,
231				Package:    clonePackage(x.Package),
232			}
233			return nil
234		})
235		return out, err
236	}
237	
238	// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
239	// 包摘要、接受或拒绝的结果及原因。
240	//
241	// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
242	// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
243	// 状态不变。相同回执（结果与原因均相同）重交只是确认已保存的那份回执：
244	// 返回原确认（登记时间保持首次成功登记时的值），不新增审计、不改写已保存
245	// 数据，也不触发落盘——即使本地保存条件当前不可用，重交仍成功返回原确认；
246	// 结果或原因改变返回 ErrConflict，与当前能否保存无关。其他身份不能代交，
247	// 不存在的交换统一拒绝。
248	//
249	// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
250	// 不提供任何受保护内容。
251	func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
252		if !actor.valid() || actor.Kind != "receiver" {
253			return ReceiptConfirmation{}, ErrAccessDenied
254		}
255		if strings.TrimSpace(exchangeID) == "" {
256			return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
257		}
258		if outcome != ReceiptAccepted && outcome != ReceiptRejected {
259			return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
260		}
261		if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
262			return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
263		}
264		if outcome == ReceiptAccepted {
265			// 接受不携带原因；统一归一化，保证重复提交判定稳定。
266			reason = ""
267		}
268	
269		var conf ReceiptConfirmation
270		err := s.mutate(func(snap *snapshot) error {
271			x := snap.Exchanges[exchangeID]
272			if x == nil || x.ReceiverID != actor.ID {
273				// 不存在或属于其他接收方/其他身份：统一拒绝。
274				return ErrAccessDenied
275			}
276			if digest != x.Digest {
277				return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
278			}
279			if x.Receipt != nil {
280				if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
281					return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
282				}
283				// 相同回执重交：只是确认已保存的那份回执，没有任何状态变更，
284				// 不落盘——即使本地保存条件当前不可用，也成功返回原确认，
285				// 登记时间保持首次成功登记时的值。
286				conf = ReceiptConfirmation{
287					ExchangeID:   x.ID,
288					Status:       x.Status,
289					Outcome:      x.Receipt.Outcome,
290					RegisteredAt: x.Receipt.RegisteredAt,
291				}
292				return errUnchanged
293			}
294	
295			now := s.now()
296			x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
297			if outcome == ReceiptAccepted {
298				x.Status = ExchangeAccepted
299			} else {
300				x.Status = ExchangeRejected
301			}
302			s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
303			conf = ReceiptConfirmation{
304				ExchangeID:   x.ID,
305				Status:       x.Status,
306				Outcome:      outcome,
307				RegisteredAt: now,
308			}
309			return nil
310		})
311		return conf, err
312	}
313	
314	// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
315	// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
316	// ErrMismatchedPatient。
317	func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
318		if !actor.valid() || !actor.IsInternal() {
319			return Exchange{}, ErrAccessDenied
320		}
321		var result Exchange
322		err := s.view(func(snap *snapshot) error {
323			x, err := requireExchange(snap, patientID, exchangeID)
324			if err != nil {
325				return err
326			}
327			result = cloneExchangeValue(x)
328			return nil
329		})
330		return result, err
331	}
332	
333	// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
334	// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
335	func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
336		if !actor.valid() || !actor.IsInternal() {
337			return nil, ErrAccessDenied
338		}
339		var result []Exchange
340		err := s.view(func(snap *snapshot) error {
341			if _, err := requirePatient(snap, patientID); err != nil {
342				return err
343			}
344			for _, x := range snap.Exchanges {
345				if x.PatientID == patientID {
346					result = append(result, cloneExchangeValue(x))
347				}
348			}
349			sort.Slice(result, func(i, j int) bool {
350				if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
351					return result[i].CreatedAt.Before(result[j].CreatedAt)
352				}
353				return result[i].ID < result[j].ID
354			})
355			return nil
356		})
357		return result, err
358	}
359	
360	func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
361		x := snap.Exchanges[exchangeID]
362		if x == nil {
363			return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
364		}
365		if x.PatientID != patientID {
366			return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
367				ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
368		}
369		return x, nil
370	}
371	
372	func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
373		for _, x := range snap.Exchanges {
374			if x.CreatorID == creatorID && x.RequestID == requestID {
375				return x
376			}
377		}
378		return nil
379	}
380	
381	// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
382	func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
383		if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
384			return false
385		}
386		if len(x.Package.Records) != len(wantedRecordIDs) {
387			return false
388		}
389		// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
390		for i, pr := range x.Package.Records {
391			if pr.RecordID != wantedRecordIDs[i] {
392				return false
393			}
394		}
395		return true
396	}
397	
398	func uniqueSortedIDs(ids []ID) []ID {
399		seen := make(map[ID]struct{}, len(ids))
400		out := make([]ID, 0, len(ids))
401		for _, id := range ids {
402			if _, ok := seen[id]; ok {
403				continue
404			}
405			seen[id] = struct{}{}
406			out = append(out, id)
407		}
408		sort.Strings(out)
409		return out
410	}
411	
412	func clonePackage(p Package) Package {
413		p.Records = append([]PackagedRecord(nil), p.Records...)
414		return p
415	}
416	
417	func cloneExchangeValue(x *Exchange) Exchange {
418		y := *x
419		y.Package = clonePackage(x.Package)
420		if x.Receipt != nil {
421			r := *x.Receipt
422			y.Receipt = &r
423		}
424		return y
425	}
426	
427	// canonicalRecord 固定摘要中每个字段的序列化顺序。
428	type canonicalRecord struct {
429		EncounterID ID     `json:"encounter_id"`
430		Category    string `json:"category"`
431		RecordID    ID     `json:"record_id"`
432		VersionID   ID     `json:"version_id"`
433		Version     int    `json:"version"`
434		EffectiveAt string `json:"effective_at"`
435		Content     string `json:"content"`
436	}
437	
438	type canonicalPackage struct {
439		PatientID  ID                `json:"patient_id"`
440		ReceiverID string            `json:"receiver_id"`
441		Records    []canonicalRecord `json:"records"`
442	}
443	
444	// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
445	// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
446	func packageDigest(p Package) string {
447		cp := canonicalPackage{
448			PatientID:  p.PatientID,
449			ReceiverID: p.ReceiverID,
450			Records:    make([]canonicalRecord, 0, len(p.Records)),
451		}
452		recs := append([]PackagedRecord(nil), p.Records...)
453		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
454		for _, r := range recs {
455			cp.Records = append(cp.Records, canonicalRecord{
456				EncounterID: r.EncounterID,
457				Category:    r.Category,
458				RecordID:    r.RecordID,
459				VersionID:   r.VersionID,
460				Version:     r.Version,
461				EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
462				Content:     r.Content,
463			})
