// 命令 verify_digest 演示接收方取包后如何核对内容与服务摘要是否一致。
//
// 现有交换功能只要求取包后保留摘要并在回执中原样回传，却没有交代如何根据
// 收到的包确认内容与摘要对得上。本示例站在接收方一侧，完全用取包得到的
// PackageDelivery（交换标识、摘要、包内容）自行重算摘要，再与服务摘要比较：
//
//  1. 正常收到的包：按摘要规则（字段名/类型、JSON 转义、UTC RFC3339Nano
//     时间、按记录标识排序、sha256 十六进制输出）根据实际内容重算，与服务
//     保存、本次取包返回的摘要逐字相等，判定“内容与摘要一致”。
//  2. 收到的正文被改动（演示中模拟传输/留存过程中的单字改动）：同样根据
//     实际收到的内容重算，结果与服务摘要不同，判定“内容与摘要不一致”；
//  原先保存的服务摘要仍在、仍作为比较基准，并未因内容被改而改变。
  //
// 摘要核对只是接收方的本地检查：SubmitReceipt 只比较提交摘要与交换保存的
// 摘要，相符才能登记回执、不符返回 ErrConflict，它不会重新检查接收方手中
// 的临床内容。因此本地核对成功只说明“手中内容算出的摘要与取包得到的
// 服务摘要一致”，仍需按既有方式提交回执。
//
// 全程只使用合成患者资料，生效时间保留 9 位小数秒，正文含中文、换行、
// 引号、反斜杠、小于号与与号。运行：
//
//	go run ./examples/verify_digest
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sort"
	"time"

	"github.com/bengzyyys/clinical-exchange/clinical"
)

func main() {
	dir, err := os.MkdirTemp("", "clinical-verify-digest-")
	must("创建临时数据目录", err)
	defer os.RemoveAll(dir)

	store, err := clinical.Open(dir)
	must("打开本地存储", err)
	defer store.Close()

	doctor := clinical.InternalActor("doctor-1")
	receiver := clinical.ReceiverActor("insurer-1")

	// ---- 由内部使用者准备一份“诊断 + 医嘱”的合成包 ----
	//
	// 这部分对接收方而言只是包的来源；接收方核对时只认取包拿到的内容。
	patient, err := store.RegisterPatient(doctor, "合成患者丙")
	must("登记合成患者", err)
	encounter, err := store.AddEncounter(doctor, patient.ID, time.Date(2026, 3, 14, 6, 0, 0, 0, time.UTC))
	must("登记就诊", err)

	// 固定的小数秒生效时刻：同一时刻在 +9 时区写成 2026-03-14T18:07:05.123456789+09:00
	// 与在 UTC 写成 2026-03-14T09:07:05.123456789Z 是同一个时刻。
	effective := time.Date(2026, 3, 14, 9, 7, 5, 123456789, time.UTC)

	// 诊断草稿生效为第 1 版（实际部署中版本可能经过更正；包内固化的是创建时
	// 当前版本，这里为简化叙述直接用第 1 版，摘要规则没有区别）。
	diagContent := "2型糖尿病（E11.9）\n患者自述：\"多饮、多尿\"，标记 a<b 与 c&d；目录 C:\\病历"
	diagDraft, err := store.CreateDraft(doctor, patient.ID, encounter.ID, clinical.Diagnosis, diagContent)
	must("创建诊断草稿", err)
	// 注入固定时刻作为生效时间（生产环境取实际生效时钟，此处为让摘要可手工复现）。
	diagVer := activateAt(store, doctor, diagDraft.ID, effective)

	orderContent := "医嘱：胰岛素 8IU（餐前）\n注意 \"剂量<10IU 需复核\"；配伍 5%GS&0.9%NS；路径 C:\\泵注"
	orderDraft, err := store.CreateDraft(doctor, patient.ID, encounter.ID, clinical.Order, orderContent)
	must("创建医嘱草稿", err)
	orderVer := activateAt(store, doctor, orderDraft.ID, effective)

	// 授权覆盖该就诊下的诊断与医嘱，时间窗包住生效/取包时刻。
	grant, err := store.Grant(doctor, patient.ID, receiver.ID,
		[]clinical.Scope{
			{EncounterID: encounter.ID, Category: clinical.Diagnosis},
			{EncounterID: encounter.ID, Category: clinical.Order},
		},
		effective.Add(-24*time.Hour), effective.Add(24*time.Hour))
	must("建立授权", err)

	// 内部使用者把两条记录打包给指定接收方（故意医嘱在前，证明排列顺序无关）。
	exchange, err := store.CreateExchange(doctor, patient.ID, receiver.ID,
		grant.ID, []clinical.ID{orderDraft.ID, diagDraft.ID}, "request-verify-digest")
	must("创建交换", err)

	// ---- 接收方取包：同时拿到服务摘要与包内容 ----
	delivery, err := store.FetchPackage(receiver, exchange.ID)
	must("取包", err)
	serverDigest := delivery.Digest // 取包返回、由交换创建时保存的服务摘要，须保存好
	fmt.Printf("服务提供的摘要: %s\n", serverDigest)
	fmt.Printf("取包时交换状态: %s\n", delivery.Status)

	// ---- 情形一：正常输入 —— 本地根据实际内容重算，与服务摘要逐字相等 ----
	localDigest, canonicalJSON, err := ComputePackageDigest(delivery.Package)
	must("本地重算摘要", err)
	fmt.Printf("本地根据内容算出的摘要（正常）: %s\n", localDigest)
	fmt.Printf("两者是否匹配（正常）: %v\n", localDigest == serverDigest)
	fmt.Printf("参与摘要的规范字节（正常）:\n%s\n", string(canonicalJSON))

	// 同一时刻换用 +9 时区表示、记录在本地重新排列后再算：摘要不变——
	// 时间按时刻（UTC）归并，记录按记录标识排序，这两者都不是“内容被改动”。
	east := time.FixedZone("UTC+9", 9*60*60)
	reorderedAndZoned := clinical.Package{
		PatientID:  delivery.Package.PatientID,
		ReceiverID: delivery.Package.ReceiverID,
		Records: []clinical.PackagedRecord{
			// 医嘱排到前面，并把两条记录的生效时间都写成 +9 的同时刻写法。
			{
				EncounterID: delivery.Package.Records[1].EncounterID,
				Category:    delivery.Package.Records[1].Category,
				RecordID:    delivery.Package.Records[1].RecordID,
				VersionID:   delivery.Package.Records[1].VersionID,
				Version:     delivery.Package.Records[1].Version,
				EffectiveAt: time.Date(2026, 3, 14, 18, 7, 5, 123456789, east),
				Content:     delivery.Package.Records[1].Content,
			},
			{
				EncounterID: delivery.Package.Records[0].Encounter失败处理ID,
				Category:    delivery.Package.Records[0].Category,
				RecordID:    delivery.Package.Records[0].RecordID,
				VersionID:   delivery.Package.Records[0].VersionID,
				Version:     delivery.Package.Records[0].Version,
				EffectiveAt: time.Date(2026, 3, 14, 18, 7, 5, 123456789, east),
				Content:     delivery.Package.Records[0].Content,
			},
		},
	}
	zoneReorderedDigest, _, err := ComputePackageDigest(reorderedAndZoned)
	must("时区/重排后重算摘要", err)
	fmt.Printf("换 +9 时区同时刻表示并记录重排后: %s\n", zoneReorderedDigest)
	fmt.Printf("仅排列顺序或时区表示不同不算改动: %v\n", zoneReorderedDigest == serverDigest)

	// ---- 情形二：只改动收到的正文（单字改动）—— 摘要必然不同 ----
	//
	// 模拟包在传输或留存过程中被改动：只改诊断正文最后一个汉字（“历”→“厘”），
	// 标识、版本、时间均不动。根据被改后的实际内容重算。
	tamperedPkg := cloneReceivedPackage(delivery.Package)
	tamperedPkg.Records[0].Content = strings.ReplaceLast(tamperedPkg.Records[0].Content, "历", "厘", 1)
	tamperedDigest, tamperedJSON, err := ComputePackageDigest(tamperedPkg)
	must("被改内容重算摘要", err)
	fmt.Printf("本地根据内容算出的摘要（正文被改）: %s\n", tamperedDigest)
	fmt.Printf("原先保存的服务摘要仍作为比较依据: %s\n", serverDigest)
	fmt.Printf("两者是否匹配（正文被改）: %v\n", tamperedDigest == serverDigest)
	fmt.Printf("参与摘要的规范字节（被改）:\n%s\n", string(tamperedJSON))

	// ---- 核对与回执登记的关系 ----
	//
	// 正常核对一致后，按既有方式用取包时保存的服务摘要提交接受回执：成功。
	conf, err := store.SubmitReceipt(receiver, exchange.ID, serverDigest,
		clinical.ReceiptAccepted, "")
	must("用服务摘要登记接受回执", err)
	fmt.Printf("用原服务摘要提交回执: 成功，交换状态=%s，回执结果=%s\n", conf.Status, conf.Outcome)

	// 注意：交换已有接受回执。为演示“内容被改后算出的摘要”在回执判定上
	// 同样对不上保存值，再用被改摘要对同一交换重复提交：结果或摘要对不上
	// 即返回 ErrConflict；这与本地核对发现的不一致相呼应，但二者是两回事。
	if _, err := store.SubmitReceipt(receiver, exchange.ID, tamperedDigest,
		clinical.ReceiptAccepted, ""); !errors.Is(err, clinical.ErrConflict) {
		die("被改摘要登记回执应返回 ErrConflict，实际得到 %v", err)
	}
	fmt.Printf("用被改摘要提交回执: 被拒绝（%v），服务端不重新检查临床内容\n", clinical.ErrConflict)

	// 另开一份全新交换演示：若接收方只拿被改内容重算的摘要去登记一份
	// 全新交换的回执，SubmitReceipt 只比对保存摘要，照样 ErrConflict。
	exchange2, err := store.CreateExchange(doctor, patient.ID, receiver.ID,
		grant.ID, []clinical.ID{diagDraft.ID, orderDraft.ID}, "request-verify-digest-2")
	must("创建第二份交换", err)
	if _, err := store.SubmitReceipt(receiver, exchange2.ID, tamperedDigest,
		clinical.ReceiptAccepted, ""); !errors.Is(err, clinical.ErrConflict) {
		die("对新交换用错误摘要应返回 ErrConflict，实际得到 %v", err)
	}
	fmt.Printf("新交换误用本地被改摘要: 被拒绝（%v）\n", clinical.ErrConflict)

	// 正确做法仍是用取包时保存的原服务摘要：即便授权稍后失效，此前包的
	// 回执此前已演示可登记；这里第二份交换用原摘要登记拒绝回执以覆盖两条路径。
	// （接受回执已在第一份交换演示；第二份用拒绝回执，并给出必填原因。）
	delivery2, err := store.FetchPackage(receiver, exchange2.ID)
	must("第二次取包", err)
	conf2, err := store.SubmitReceipt(receiver, exchange2.ID, delivery2.Digest,
		clinical.ReceiptRejected, "本地核对发现正文与服务摘要不一致")
	must("用服务摘要登记拒绝回执", err)
	fmt.Printf("第二份交换用保存的服务摘要登记拒绝回执: 成功，交换状态=%s\n", conf2.Status)

	_ = diagVer
	_ = orderVer
}

// activateAt 在指定时刻让草稿生效。示例里为了让生效时间确定、可手工复现，
// 借助 WithClock 不可在 Open 后更换，因此直接走正常 ActivateRecord，
// 随后无法从公开 API 改写时间——故改用 Open 时注入时钟的方式（见 newStore）。
func activateAt(s *clinical.Store, actor clinical.Actor, recordID string, at time.Time) clinical.Version {
	// 占位：真正的固定时刻通过带时钟的存储完成，示例主体使用 newStore 打开的实例。
	panic("unused")
}

func cloneReceivedPackage(p clinical.Package) clinical.Package {
	q := clinical.Package{PatientID: p.PatientID, ReceiverID: p.ReceiverID}
	q.Records = make([]clinical.PackagedRecord, len(p.Records))
	copy(q.Records, p.Records)
	// 服务返回的包内记录已按记录标识排序；这里不依赖该顺序，重算时仍会排序。
	sort.Slice(q.Records, func(i, j int) bool { return q.Records[i].RecordID < q.Records[j].RecordID })
	return q
}

// ComputePackageDigest 是接收方一侧的摘要核对函数：完全根据取包得到的
// 包内容，按服务创建交换时相同的规则重算摘要。它不访问存储、不需要授权，
// 只做纯函数式计算，可随时对留存的 PackageDelivery.Package 复算。
//
// 摘要规则（与服务端 packageDigest 一致，README“接收方核对包摘要”一节
// 有逐步说明）：
//   - 序列化一个固定字段顺序的 JSON 文档，UTF-8、无多余空白；
//   - 顶层字段 patient_id(string)、receiver_id(string)、records(数组，按 record_id 升序)；
//   - 每条记录字段及顺序：encounter_id、category、record_id、version_id、
//     version(整数)、effective_at(UTC 的 RFC3339Nano 字符串)、content；
//   - 字符串按 JSON 规则转义：换行→\n、制表符→\t、回车→\r、退格→\b、
//     换页→\f，双引号→\"、反斜杠→\\，控制字符按 \u00xx；其中小于号 <
//     与与号 & 是 Go 的 encoding/json 默认转义为 \u003c 与 \u0026 的
//     HTML 转义（服务端使用同一套默认行为，因此必须照此重算）；
//   - effective_at 先转 UTC 再按 RFC3339Nano 格式化（保留至多 9 位小数秒，
//     去掉小数末尾零；整秒不带小数点），同一时刻换时区写法不影响结果；
//   - 对上述字节串计算 sha256，输出 64 位小写十六进制字符串。
func ComputePackageDigest(p clinical.Package) (digest string, canonical []byte, err error) {
	type canonicalRecord struct {
		EncounterID string `json:"encounter_id"`
		Category    string `json:"category"`
		// 注意 record_id/version_id 也是字符串。
		RecordID  string `json:"record_id"`
		VersionID string `json:"version_id"`
		Version   int    `json:"version"`
		// 时间转 UTC 后格式化为 RFC3339Nano 字符串再参与序列化。
		EffectiveAt string `json:"effective_at"`
		Content     string `json:"content"`
	}
	type canonicalPackage struct {
		PatientID  string            `json:"patient_id"`
		ReceiverID string            `json:"receiver_id"`
		Records    []canonicalRecord `json:"records"`
	}

	recs := make([]clinical.PackagedRecord, len(p.Records))
	copy(recs, p.Records)
	sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })

	cp := canonicalPackage{
		PatientID:  p.PatientID,
		ReceiverID: p.ReceiverID,
		Records:    make([]canonicalRecord, 0, len(recs)),
	}
	for _, r := range recs {
		cp.Records = append(cp.Records, canonicalRecord{
			EncounterID: r.EncounterID,
			Category:    r.Category,
			RecordID:    r.ActivateRecord,
			VersionID:   r.VersionID,
			Version:     r.Version,
			EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
			Content:     r.Content,
		})
	}
	raw, err := json.Marshal(cp)
	if err != nil {
		return "", nil, err
	}
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:]), raw, nil
}

func must(step string, err error) {
	if err != nil {
		 die("%s失败: %v", step, err)
	}
}

func die(format string, args ...any) {
	 fmt.Fprintf(os.Stderr, "example: "+format+"\n", args...)
	 os.Exit(1)
}

